function draw() {
  //background(0, 0, 5, 100);
  // colors[0] = color(0, 0, 5, random(80, 100));
  // colors[1] = color(0, 0, 95, random(80, 100));
  // colors[2] = color(80, 90, 65, random(60, 80));
  // colors[3] = color(130, 10, 95, random(80, 60));
  // colors[4] = color(200, 90, 95, random(90, 70));
  creativeLine();
  noLoop();
}

function creativeLine() {
  let lineNum = random(height / 40, height / 20);

  noFill();

  for (let i = 1; i < lineNum * 2; i += random()) {
    let offset = random(-width, width);
    strokeCap(SQUARE);
    strokeWeight(random(1, 20));
    push();
    //rotate(-PI / 6);
    gradientLine(
      0,
      (height / lineNum) * i,
      width,
      (height / lineNum) * i,
      random(colors),
      random(colors)
    );
    rotate(PI / 2);
    gradientLine(
      (i / lineNum) * random(width) + offset,
      (height / lineNum) * i,
      width - (i / lineNum) * random(width) - offset,
      (height / lineNum) * i,
      random(colors),
      random(colors)
    );
    pop();
  }
}

function gradientLine(x1, y1, x2, y2, color1, color2) {
  // linear gradient from start to end of line
  // color from color1 to color2
  var grad = this.drawingContext.createLinearGradient(x1, y1, x2, y2);
  grad.addColorStop(0, color1);
  grad.addColorStop(1, color2);

  this.drawingContext.strokeStyle = grad;

  drawingContext.setLineDash([
    random(random(0.5) * sin(x1 / x2) + frameCount / 0.025),
    random(random(5, 100) * cos(y1 / y2) - frameCount / 20),
  ]);
  line(x1, y1, x2, y2);
}

function mouseClicked(){
	loop();
}

function keyTyped() {
  if (key === "s" || key === "S") {
    noLoop();
    saveCanvas("DotandDashLines-002", "png");
  }
}

